let AC=null;function ac(){if(!AC)AC=new(window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC}function tone(m,d=.6){let a=ac(),t=a.currentTime,f=m2f(m,+document.getElementById('a4').value),master=a.createGain();master.gain.setValueAtTime(.0001,t);master.gain.exponentialRampToValueAtTime(.22,t+.012);master.gain.exponentialRampToValueAtTime(.06,t+.2);master.gain.exponentialRampToValueAtTime(.0001,t+d);master.connect(a.destination);[1,2,3,4].forEach((h,i)=>{let o=a.createOscillator(),g=a.createGain();o.type=i?'sine':'triangle';o.frequency.value=f*h;g.gain.value=[1,.28,.14,.07][i];o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.03)})}
let playing=false,start=0,raf=0,target=null;function resize(){let r=F.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);C.width=Math.floor(r.width*d);C.height=Math.floor(r.height*d);X.setTransform(d,0,0,d,0,0)}function kx(m){let e=keys.get(m),kr=e.getBoundingClientRect(),vr=V.getBoundingClientRect();return kr.left-vr.left+kr.width/2}function rr(x,y,w,h,r){X.beginPath();X.roundRect?X.roundRect(x,y,w,h,r):(X.rect(x,y,w,h));X.fill()}
function draw(t=0){resize();let w=F.clientWidth,h=F.clientHeight;X.fillStyle='#050b11';X.fillRect(0,0,w,h);X.strokeStyle='#ffffff0d';for(let y=h%48;y<h;y+=48){X.beginPath();X.moveTo(0,y);X.lineTo(w,y);X.stroke()}for(const n of DEMO){let y=h-3-(n.t-t)*72,hh=Math.max(18,n.d*72);if(y<-hh||y>h+hh)continue;let x=kx(n.m);X.fillStyle='#ffb347';rr(x-17,y-hh,34,hh,6);X.fillStyle='#17202a';X.textAlign='center';X.font='11px system-ui';X.fillText(name(n.m),x,y-hh/2+4)}}function setTarget(m){if(target!==null)keys.get(target)?.classList.remove('target');target=m;if(m!==null)keys.get(m)?.classList.add('target');document.getElementById('targetLabel').textContent=m===null?'No target':name(m);match(lastMidi)}
