let stream=null,src=null,ana=null,timer=null,listening=false,buf=null,down=null,recent=[],lastMidi=null,lastAt=0;const listen=document.getElementById('listen'),dot=document.getElementById('dot'),micStatus=document.getElementById('micStatus'),heard=document.getElementById('heardNote'),midiEl=document.getElementById('midi'),freqEl=document.getElementById('freq'),centsEl=document.getElementById('cents'),banner=document.getElementById('banner');listen.onclick=()=>listening?stopListen():startListen();
async function startListen(){if(!navigator.mediaDevices?.getUserMedia)return alert('Microphone access needs a modern HTTPS browser.');try{let a=ac();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false,channelCount:1},video:false});src=a.createMediaStreamSource(stream);ana=a.createAnalyser();ana.fftSize=16384;ana.smoothingTimeConstant=0;src.connect(ana);buf=new Float32Array(ana.fftSize);down=new Float32Array(ana.fftSize/4);listening=true;listen.classList.add('on');listen.textContent='■ Stop listening';dot.classList.add('live');micStatus.textContent='Listening';banner.innerHTML='Listening… play <b>one note</b> on the real piano.';log(`Mic started: ${a.sampleRate} Hz`);loop()}catch(e){log('Mic error: '+e.message);alert('Microphone access failed. Check HTTPS and browser microphone permission.')}}function stopListen(){listening=false;clearTimeout(timer);try{src?.disconnect()}catch(e){}stream?.getTracks().forEach(t=>t.stop());stream=src=ana=null;listen.classList.remove('on');listen.textContent='🎤 Listen';dot.classList.remove('live');micStatus.textContent='Microphone off';clearHeard();banner.textContent='Microphone stopped';log('Mic stopped')}
function loop(){if(!listening||!ana)return;ana.getFloatTimeDomainData(buf);let rms=0;for(let i=0,j=0;i<buf.length;i+=4,j++){let v=(buf[i]+buf[i+1]+buf[i+2]+buf[i+3])*.25;down[j]=v;rms+=v*v}rms=Math.sqrt(rms/down.length);if(rms>=+document.getElementById('sens').value){let r=yin(down,ac().sampleRate/4,27,4300);if(r&&r.c>=+document.getElementById('conf').value)accept(r.f,r.c);else decay()}else decay();timer=setTimeout(loop,115)}
function yin(b,sr,minF,maxF){let n=b.length,min=Math.max(2,Math.floor(sr/maxF)),max=Math.min(Math.floor(sr/minF),Math.floor(n/2)-1),d=new Float32Array(max+1);for(let t=min;t<=max;t++){let sum=0,lim=Math.min(n-t,2600);for(let i=0;i<lim;i++){let q=b[i]-b[i+t];sum+=q*q}d[t]=sum/lim}let run=0,c=new Float32Array(max+1);for(let t=min;t<=max;t++){run+=d[t];c[t]=run?d[t]*((t-min+1)/run):1}let te=-1;for(let t=min+1;t<max;t++)if(c[t]<.16&&c[t]<=c[t-1]&&c[t]<=c[t+1]){te=t;while(te+1<max&&c[te+1]<c[te])te++;break}if(te<0){let best=1;for(let t=min;t<=max;t++)if(c[t]<best){best=c[t];te=t}if(te<0||best>.32)return null}let bt=te;if(te>min&&te<max){let a=c[te-1],b1=c[te],cc=c[te+1],den=2*b1-cc-a;if(Math.abs(den)>1e-8)bt=te+(cc-a)/(2*den)}return{f:sr/bt,c:Math.max(0,1-c[te])}}
function mode(a){let M=new Map(),best=a[a.length-1],bc=0;for(const x of a){let c=(M.get(x)||0)+1;M.set(x,c);if(c>=bc){bc=c;best=x}}return best}function accept(f,c){let a=+document.getElementById('a4').value,m=Math.round(f2m(f,a));if(m<21||m>108)return decay();recent.push(m);if(recent.length>7)recent.shift();m=mode(recent);if(recent.length>=3&&recent.filter(x=>x===m).length<3)return;let cent=1200*Math.log2(f/m2f(m,a));lastAt=performance.now();show(m,f,cent,c)}function show(m,f,cent,c){if(lastMidi!==null&&lastMidi!==m)keys.get(lastMidi)?.classList.remove('heard');lastMidi=m;keys.get(m)?.classList.add('heard');heard.textContent=name(m);midiEl.textContent=`MIDI ${m} · ${(c*100).toFixed(0)}% confidence`;freqEl.textContent=f.toFixed(f<100?1:0);centsEl.textContent=(cent>=0?'+':'')+cent.toFixed(0);banner.innerHTML=`Heard <b style="color:#29d6ff">${name(m)}</b> · ${f.toFixed(1)} Hz`;match(m)}function decay(){if(performance.now()-lastAt>430)clearHeard()}function clearHeard(){if(lastMidi!==null)keys.get(lastMidi)?.classList.remove('heard');lastMidi=null;recent=[];heard.textContent='—';midiEl.textContent='Waiting';freqEl.textContent=centsEl.textContent='—';match(null)}function match(m){let e=document.getElementById('match');e.className='v';if(target===null)return e.textContent='—';if(m===null){e.textContent='Listen';e.classList.add('bad')}else if(m===target){e.textContent='Correct';e.classList.add('good')}else{e.textContent=m<target?'Too low':'Too high';e.classList.add('bad')}}
